package com.rootopathy.careos.administration.api;
import com.rootopathy.careos.governance.domain.IdempotencyOutcome;
import com.rootopathy.careos.administration.application.ServiceCatalogueService;import com.rootopathy.careos.administration.domain.ServiceCatalogue;import com.rootopathy.careos.identity.api.AuthenticationSessionState;import com.rootopathy.careos.shared.api.*;import com.rootopathy.careos.shared.domain.AuthenticatedActor;import jakarta.servlet.http.*;import java.time.Instant;import java.util.UUID;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController public class ServiceCatalogueController{private final ServiceCatalogueService service;public ServiceCatalogueController(ServiceCatalogueService s){service=s;}@GetMapping("/api/v1/organizations/{organizationId}/services")ResponseEntity<ServiceCatalogue> directory(@PathVariable UUID organizationId,Authentication authentication,HttpServletRequest request){var a=actor(authentication);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(service.directory(new ServiceCatalogueService.Read(organizationId,a.id(),CorrelationIdFilter.from(request))));}@PostMapping("/api/v1/organizations/{organizationId}/services")ResponseEntity<String> create(@PathVariable UUID organizationId,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Write body,Authentication authentication,HttpServletRequest request){var a=actor(authentication);return response(service.create(command(organizationId,a.id(),request,key,null,null,body)));}@PutMapping("/api/v1/organizations/{organizationId}/services/{serviceId}")ResponseEntity<String> update(@PathVariable UUID organizationId,@PathVariable UUID serviceId,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String etag,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Write body,Authentication authentication,HttpServletRequest request){var a=actor(authentication);return response(service.update(command(organizationId,a.id(),request,key,etag,serviceId,body)));}@PostMapping("/api/v1/organizations/{organizationId}/services/{serviceId}/activations")ResponseEntity<String> activate(@PathVariable UUID organizationId,@PathVariable UUID serviceId,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String etag,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Lifecycle body,Authentication authentication,HttpServletRequest request){return lifecycle(organizationId,serviceId,etag,key,body,authentication,request,true);}@PostMapping("/api/v1/organizations/{organizationId}/services/{serviceId}/retirements")ResponseEntity<String> retire(@PathVariable UUID organizationId,@PathVariable UUID serviceId,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String etag,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Lifecycle body,Authentication authentication,HttpServletRequest request){return lifecycle(organizationId,serviceId,etag,key,body,authentication,request,false);}private ResponseEntity<String> lifecycle(UUID o,UUID id,String etag,String key,Lifecycle body,Authentication authentication,HttpServletRequest request,boolean activate){var a=actor(authentication);var session=request.getSession(false);var c=new ServiceCatalogueService.Lifecycle(o,a.id(),CorrelationIdFilter.from(request),key,etag,id,body.reason(),assurance(session,AuthenticationSessionState.RECENT_AUTHENTICATION_AT),assurance(session,AuthenticationSessionState.MFA_AUTHENTICATED_AT));return response(activate?service.activate(c):service.retire(c));}private static ServiceCatalogueService.Write command(UUID o,UUID actor,HttpServletRequest request,String key,String etag,UUID id,Write b){return new ServiceCatalogueService.Write(o,actor,CorrelationIdFilter.from(request),key,etag,id,b.serviceCode(),b.displayName(),b.clinicalName(),b.description(),b.codingSystem(),b.codingCode(),b.ownerResponsibilityId(),b.reason());}private static ResponseEntity<String> response(IdempotencyOutcome r){return ResponseEntity.status(r.response().statusCode()).cacheControl(CacheControl.noStore()).contentType(MediaType.APPLICATION_JSON).body(r.response().bodyJson());}private static AuthenticatedActor actor(Authentication a){if(a==null||!(a.getPrincipal() instanceof AuthenticatedActor actor))throw new ApiProblemException(HttpStatus.UNAUTHORIZED,"authentication-required","Authentication required","A valid authenticated session is required.");return actor;}private static Instant assurance(HttpSession s,String key){var v=s==null?null:s.getAttribute(key);return v instanceof Long ms?Instant.ofEpochMilli(ms):null;}public record Write(String serviceCode,String displayName,String clinicalName,String description,String codingSystem,String codingCode,UUID ownerResponsibilityId,String reason){}public record Lifecycle(String reason){}
}
